{
  "name": "BakeVault - Premium Baking Supplies",
  "description": "A professional one-page storefront for BakeVault, providing high-quality baking ingredients and supplies to Lagos and beyond. Features product browsing, category filtering, and WhatsApp-integrated ordering."
}

export type Category = 
  | 'Yogurt & Dairy Starters'
  | 'Milk Flavorings & Essences'
  | 'Preservatives & Additives'
  | 'Syrups & Toppings'
  | 'Milk Flavouring Powders (Bulk)'
  | 'Margarine & Spreads'
  | 'Baking Ingredients'
  | 'Food Coloring'
  | 'Other Products';

export interface Product {
  id: string;
  name: string;
  category: Category;
  description?: string;
  price: string; // "Contact for price" or numeric if available
  image: string;
}

export interface CartItem extends Product {
  quantity: number;
}

import React from 'react';

interface HeaderProps {
  cartCount: number;
  onOpenCart: () => void;
}

const Header: React.FC<HeaderProps> = ({ cartCount, onOpenCart }) => {
  return (
    <header className="sticky top-0 z-40 w-full bg-white border-b border-gray-200 shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16 sm:h-20">
          <div className="flex-shrink-0 flex items-center gap-2">
            <div className="bg-indigo-700 text-white p-2 rounded-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-gray-900 leading-none">BakeVault</h1>
              <p className="text-[10px] uppercase tracking-wider text-indigo-600 font-semibold mt-1">Premium Baking Supplies</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={onOpenCart}
              className="relative p-2 text-gray-600 hover:text-indigo-600 transition-colors bg-gray-100 rounded-full"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
