import React, { useState, useMemo } from 'react';
import Header from './components/Header';
import ProductCard from './components/ProductCard';
import Cart from './components/Cart';
import { PRODUCTS, CATEGORIES, WHATSAPP_NUMBER } from './constants';
import { Product, CartItem, Category } from './types';

const App: React.FC = () => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  const filteredProducts = useMemo(() => {
    return PRODUCTS.filter(product => {
      const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
      const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           product.category.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [selectedCategory, searchQuery]);

  const addToCart = (product: Product) => {
    setCartItems(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const updateCartQuantity = (id: string, delta: number) => {
    setCartItems(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeFromCart = (id: string) => {
    setCartItems(prev => prev.filter(item => item.id !== id));
  };

  return (
    <div className="min-h-screen flex flex-col bg-brand-cream selection:bg-brand-orange/20 selection:text-brand-brown font-sans">
      <Header cartCount={cartItems.reduce((acc, i) => acc + i.quantity, 0)} onOpenCart={() => setIsCartOpen(true)} />

      {/* Hero Section with Animated Background */}
      <section className="relative h-[600px] sm:h-[700px] flex items-center overflow-hidden bg-brand-darkGray">
        {/* Animated Background Layer */}
        <div className="absolute inset-0 z-0">
          <img 
            src="https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&q=80&w=2000" 
            alt="Baking Background"
            className="w-full h-full object-cover animate-ken-burns opacity-60"
          />
          <div className="absolute inset-0 hero-gradient z-10"></div>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-20 w-full">
          <div className="max-w-3xl animate-fade-in-up">
            <div className="mb-6">
              <span className="inline-flex items-center px-4 py-1.5 rounded-full bg-brand-orange/20 backdrop-blur-md text-brand-orange text-[10px] font-bold tracking-[0.2em] uppercase border border-brand-orange/30 shadow-sm">
                Uncompromising Quality Guaranteed
              </span>
            </div>

            <h2 className="text-4xl sm:text-6xl lg:text-7xl font-extrabold mb-8 leading-[1.1] font-display text-white">
              The Secret Behind Nigeria's <span className="text-brand-orange brightness-125 drop-shadow-lg">Finest Bakes.</span>
            </h2>
            <p className="text-white/90 text-lg sm:text-xl mb-12 max-w-2xl leading-relaxed font-medium">
              From artisan loaves to masterpiece cakes, we provide the foundational ingredients that make every recipe a success. Authentic dairy starters, premium essences, and quality margarines available for both home kitchens and professional bakeries.
