          <img 
            src="https://images.unsplash.com/photo-1517433670267-24daaa5e206e?auto=format&fit=crop&q=80&w=2000" 
            alt="Baking Ingredients"
            className="w-full h-full object-cover animate-ken-burns opacity-50"
          />
          <div className="absolute inset-0 hero-gradient z-10"></div>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-20 w-full animate-fade-up">
          <div className="max-w-3xl">
            <span className="inline-flex items-center px-4 py-1.5 rounded-full bg-brand-orange/20 backdrop-blur-md text-brand-orange text-[10px] font-bold tracking-[0.2em] uppercase border border-brand-orange/30 mb-8 shadow-sm">
              Your Baking Success, Secured
            </span>
            <h2 className="text-4xl sm:text-6xl lg:text-7xl font-extrabold mb-8 leading-[1.1] font-display text-white">
              The Vault of Premium <span className="text-brand-orange brightness-125">Ingredients.</span>
            </h2>
            <p className="text-white/90 text-lg sm:text-xl mb-12 max-w-2xl leading-relaxed font-medium">
              We empower Nigeria's professional and home bakers with the foundation of greatness. Sourcing only the most reliable brands for your masterpiece bakes.
            </p>
            <div className="flex flex-wrap gap-5">
              <button 
                onClick={() => handleCategorySelect('All')}
                className="bg-brand-orange text-white font-extrabold px-10 py-5 rounded-2xl hover:bg-white hover:text-brand-brown transition-all shadow-2xl active:scale-95 font-display text-lg"
              >
                Browse Catalog
              </button>
            </div>
          </div>
        </div>
        <div className="absolute bottom-0 left-0 w-full h-24 bg-gradient-to-t from-brand-cream to-transparent z-20"></div>
      </section>

      {/* Main Content Hub */}
      <main className="flex-grow max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20 w-full" id="catalog">

        {/* Search Bar - Permanent */}
        <div className="relative w-full max-w-2xl mx-auto mb-16">
          <input 
            type="text" 
            placeholder="Search ingredients, brands, or categories..."
            className="w-full bg-white border-2 border-orange-100 rounded-3xl px-8 py-5 pl-16 focus:outline-none focus:ring-4 focus:ring-brand-orange/10 focus:border-brand-orange transition-all shadow-xl font-medium h-16 sm:h-20"
