                    <div className="mb-3 text-brand-orange group-hover:scale-110 transition-transform">
                      <svg className="w-10 h-10 sm:w-12 sm:h-12 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                         <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                      </svg>
                    </div>
                    <span className="text-xs sm:text-sm font-extrabold text-brand-darkGray font-display uppercase tracking-wider line-clamp-2">{cat}</span>
                  </div>
                </button>
              ))}
            </div>

            {/* Featured Section */}
            <div className="mb-24">
              <div className="flex items-end justify-between mb-10 border-b border-orange-100 pb-6">
                <div>
                  <h3 className="text-2xl font-extrabold text-brand-darkGray font-display uppercase tracking-tight">Vault Favorites</h3>
