                  <ProductCard key={product.id} product={product} onAddToCart={addToCart} />
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Results View (When Category is selected or searching) */}
        {(selectedCategory !== 'All' || searchQuery) && (
          <div id="results-section" className="animate-fade-up">
            <div className="mb-12 flex flex-col sm:flex-row sm:items-center justify-between gap-6">
              <div>
                <button 
                  onClick={() => setSelectedCategory('All')}
                  className="flex items-center gap-2 text-brand-brown font-bold text-xs uppercase tracking-widest hover:text-brand-orange transition-colors mb-4 group"
                >
                  <svg className="w-4 h-4 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7" />
                  </svg>
                  Back to Hub
                </button>
                <h3 className="text-3xl font-extrabold text-brand-darkGray font-display tracking-tight flex items-center gap-4 uppercase">
                  {selectedCategory === 'All' ? 'Full Results' : selectedCategory}
                  <span className="text-sm font-medium normal-case text-brand-darkGray/30 tracking-normal">({filteredProducts.length} items)</span>
                </h3>
              </div>

              {/* Mini Scroll Filter */}
              <div className="flex items-center gap-2 overflow-x-auto pb-2 scrollbar-hide">
