            <h4 className="font-extrabold text-2xl text-brand-darkGray mb-4 font-display">100% Authentic</h4>
            <p className="text-brand-darkGray/60 leading-relaxed max-w-xs font-medium">Every ingredient in our inventory meets strict quality standards. Your reputation depends on it.</p>
          </div>
          <div className="flex flex-col items-center text-center group">
            <div className="bg-brand-teal/10 w-20 h-20 rounded-[28px] flex items-center justify-center mb-8 text-brand-teal transition-all shadow-sm">
              <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
