          <div className="flex flex-col items-center text-center group">
            <div className="bg-brand-teal/10 w-20 h-20 rounded-[28px] flex items-center justify-center mb-8 text-brand-teal transition-all shadow-sm">
              <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" />
              </svg>
            </div>
            <h4 className="font-extrabold text-2xl text-brand-darkGray mb-4 font-display">Fair Pricing</h4>
            <p className="text-brand-darkGray/60 leading-relaxed max-w-xs font-medium">We offer transparent wholesale rates for bulk orders and competitive retail prices for home bakers.</p>
