                <span className="font-extrabold text-2xl tracking-tighter font-display text-white">BakeVault</span>
             </div>
             <p className="text-white/30 text-xs font-medium">© {new Date().getFullYear()} BakeVault. Empowering Nigeria's Baking Community.</p>
          </div>

          <div className="flex flex-col items-center md:items-start gap-4">
            <h5 className="font-display font-bold text-lg text-brand-orange uppercase tracking-widest mb-2">Connect</h5>
            <a href="https://instagram.com/bakevaultlagos" target="_blank" className="text-white/60 hover:text-white transition-colors">@bakevaultlagos</a>
            <a href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" className="text-white/60 hover:text-white transition-colors">WhatsApp Direct</a>
          </div>

          <div className="text-center md:text-right">
             <h5 className="font-display font-bold text-lg text-brand-orange uppercase tracking-widest mb-4">Lagos hub</h5>
             <p className="text-brand-orange font-bold font-display">sales@bakevault.com.ng</p>
             <p className="text-brand-orange font-bold font-display mt-1">+{WHATSAPP_NUMBER}</p>
          </div>
        </div>
      </footer>

      <Cart 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cartItems} 
        onUpdateQuantity={updateCartQuantity}
        onRemove={removeFromCart}
      />
    </div>
  );
};

export default App;
